    metaTitle: "Annaprashan Sanskar — Vidhi, Cost, Pandit Booking | Vedic Tatva",
    metaDescription: "Book Annaprashan Sanskar — the Vedic 'first solid food' ceremony for a baby aged 6 months. Verified pandits with hawan, sweet kheer feeding, and traditional career-divination tray.",
